{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "ThH, a morphinan opioid, has very low oral bioavailability in humans, but its bulky N-cyclopropylmethyl and thiophene-containing side chain drive extensive first-pass metabolism; codeine's N-methyl, 3-methoxy, 6-hydroxy morphinan lacks these liabilities and is known to have much higher oral bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "M6G has poor oral bioavailability because it is a polar glucuronide conjugate; codeine is a lipophilic tertiary amine with good membrane permeability, so this low-F phenotype does not transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine shows very low systemic availability (mean 4.9%) due to extensive first-pass metabolism, but its benzoquinolizine scaffold and ketone functionality differ from codeine; codeine's known absolute oral bioavailability is approximately 50%, exceeding the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Codeine is a small, lipophilic, weakly basic morphinan with N-methyl, 3-methoxy, and 6-hydroxy substituents; its absolute oral bioavailability in humans is approximately 50%, well above the 20% threshold. The low-F analogues provided are either polar conjugates, quaternary ammonium salts, bulky N-substituted morphinans, or unrelated scaffolds with extensive first-pass metabolism, so their low-F phenotypes do not transfer to codeine.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for codeine is included in the provided evidence; a direct human IV/oral comparison would remove reliance on external knowledge.",
    "Fasted-state-specific absolute bioavailability data for codeine are not explicitly provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

